+int btck_witness_stack_to_bytes(const btck_WitnessStack* witness_stack, btck_WriteBytes writer, void* user_data)
+{
+    try {
+        WriterStream ws{writer, user_data};
+        ws << btck_WitnessStack::get(witness_stack).stack;
+        return 0;
+    } catch (...) {
+        return -1;
+    }
+}
